import json

with open('output/report_stats.json') as f:
    stats = json.load(f)

# Now generate the HTML report with embedded SVG charts
# I'll use inline SVG for simple charts and Chart.js via CDN for complex ones

html = '''<!DOCTYPE html>
<html lang="en">
<head>
<meta charset="UTF-8">
<meta name="viewport" content="width=device-width, initial-scale=1.0">
<title>EV Charging Network Performance & Grid Optimization Analytics Report</title>
<script src="https://cdn.jsdelivr.net/npm/chart.js@4.4.1/dist/chart.umd.min.js"></script>
<style>
  :root {
    --bg: #f4f6f9;
    --card: #ffffff;
    --text: #1a1a2e;
    --muted: #5a5a6e;
    --accent: #2563eb;
    --accent2: #059669;
    --accent3: #d97706;
    --accent4: #dc2626;
    --border: #e2e8f0;
    --shadow: 0 4px 6px -1px rgba(0,0,0,0.05), 0 2px 4px -2px rgba(0,0,0,0.05);
  }
  * { box-sizing: border-box; }
  body { margin: 0; font-family: -apple-system, BlinkMacSystemFont, "Segoe UI", Roboto, "Helvetica Neue", Arial, sans-serif; background: var(--bg); color: var(--text); line-height: 1.6; }
  .container { max-width: 1200px; margin: 0 auto; padding: 24px; }
  header { background: linear-gradient(135deg, #0f172a 0%, #1e293b 100%); color: #fff; padding: 40px 24px; border-radius: 12px; margin-bottom: 24px; }
  header h1 { margin: 0 0 8px; font-size: 1.8rem; }
  header p { margin: 0; opacity: 0.85; font-size: 1rem; }
  .meta { display: flex; gap: 24px; margin-top: 16px; flex-wrap: wrap; font-size: 0.9rem; opacity: 0.8; }
  .kpi-banner { display: grid; grid-template-columns: repeat(auto-fit, minmax(180px, 1fr)); gap: 16px; margin-bottom: 24px; }
  .kpi-card { background: var(--card); border-radius: 12px; padding: 20px; box-shadow: var(--shadow); border-left: 4px solid var(--accent); }
  .kpi-card.green { border-left-color: var(--accent2); }
  .kpi-card.amber { border-left-color: var(--accent3); }
  .kpi-card.red { border-left-color: var(--accent4); }
  .kpi-label { font-size: 0.75rem; text-transform: uppercase; letter-spacing: 0.05em; color: var(--muted); margin-bottom: 4px; }
  .kpi-value { font-size: 1.6rem; font-weight: 700; color: var(--text); }
  .kpi-sub { font-size: 0.8rem; color: var(--muted); margin-top: 4px; }
  .section { background: var(--card); border-radius: 12px; padding: 28px; margin-bottom: 24px; box-shadow: var(--shadow); }
  .section h2 { margin: 0 0 8px; font-size: 1.3rem; display: flex; align-items: center; gap: 10px; }
  .section h2 .num { background: var(--accent); color: #fff; width: 28px; height: 28px; display: inline-flex; align-items: center; justify-content: center; border-radius: 50%; font-size: 0.85rem; }
  .section p.lead { margin: 0 0 20px; color: var(--muted); font-size: 0.95rem; }
  .grid-2 { display: grid; grid-template-columns: repeat(auto-fit, minmax(320px, 1fr)); gap: 24px; }
  .grid-3 { display: grid; grid-template-columns: repeat(auto-fit, minmax(260px, 1fr)); gap: 24px; }
  .chart-wrap { position: relative; height: 300px; margin: 16px 0; }
  .chart-wrap.tall { height: 380px; }
  table { width: 100%; border-collapse: collapse; font-size: 0.9rem; margin-top: 12px; }
  th, td { text-align: left; padding: 10px 12px; border-bottom: 1px solid var(--border); }
  th { background: #f8fafc; font-weight: 600; color: var(--muted); font-size: 0.8rem; text-transform: uppercase; }
  tr:hover td { background: #f8fafc; }
  .badge { display: inline-block; padding: 2px 8px; border-radius: 999px; font-size: 0.75rem; font-weight: 600; }
  .badge-peak { background: #fee2e2; color: #991b1b; }
  .badge-off { background: #d1fae5; color: #065f46; }
  .badge-urban { background: #dbeafe; color: #1e40af; }
  .badge-highway { background: #fef3c7; color: #92400e; }
